function main(): void {
var obj = {};

obj[Symbol.toPrimitive] = 42;
assert.throws(TypeError, function() {
  isFinite(obj);
}, "number");

obj[Symbol.toPrimitive] = "";
assert.throws(TypeError, function() {
  isFinite(obj);
}, "string");

obj[Symbol.toPrimitive] = true;
assert.throws(TypeError, function() {
  isFinite(obj);
}, "boolean");

obj[Symbol.toPrimitive] = Symbol.toPrimitive;
assert.throws(TypeError, function() {
  isFinite(obj);
}, "symbol");

obj[Symbol.toPrimitive] = {};
assert.throws(TypeError, function() {
  isFinite(obj);
}, "object");
}
main();

